export interface ConnectorConfig {
  /** Zendesk subdomain (e.g., 'mycompany' for mycompany.zendesk.com) */
  zendeskSubdomain: string;
  /** Zendesk API access token (Bearer auth). Typically from ZENDESK_ACCESS_TOKEN env var. */
  zendeskAccessToken: string;
  /** Intercom App ID used to construct conversation URL if not provided in webhook payload. */
  intercomAppId?: string;
  /** Tag name that should trigger ticket creation. Defaults to 'refund'. */
  refundTagName?: string;
  /** Injected fetch for testing. */
  fetch?: typeof fetch;
}

export interface IntercomWebhookPayload {
  type: string;
  topic: string;
  data: {
    item: {
      type: string;
      id: string;
      url?: string;
    };
    tag?: {
      name: string;
    };
  };
}

export interface HandleResult {
  ticketId: number;
  subject: string;
  description: string;
}

const DEFAULT_REFUND_TAG = 'refund';
const INTERCOM_URL_TEMPLATE = 'https://app.intercom.com/a/apps/{appId}/inbox/shared/all/conversation/{conversationId}';

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch;
}

function buildConversationUrl(conversationId: string, payloadUrl: string | undefined, intercomAppId: string | undefined): string {
  if (payloadUrl && !payloadUrl.includes('<app_id>')) {
    return payloadUrl;
  }
  if (intercomAppId) {
    return INTERCOM_URL_TEMPLATE.replace('{appId}', intercomAppId).replace('{conversationId}', conversationId);
  }
  // Fallback: use payload URL even with placeholder, or construct minimal URL
  return payloadUrl ?? `https://app.intercom.com/conversation/${conversationId}`;
}

export async function handle(payload: IntercomWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  const fetchImpl = getFetch(config);

  // Validate required fields
  if (!payload.type) throw new Error('Missing required field: type');
  if (!payload.topic) throw new Error('Missing required field: topic');
  if (!payload.data?.item?.type) throw new Error('Missing required field: data.item.type');
  if (!payload.data?.item?.id) throw new Error('Missing required field: data.item.id');

  // Verify this is the expected webhook topic
  if (payload.topic !== 'conversation_part.tag.created') {
    throw new Error(`Unexpected webhook topic: ${payload.topic}. Expected 'conversation_part.tag.created'.`);
  }

  // Check tag name if present
  const refundTagName = config.refundTagName ?? DEFAULT_REFUND_TAG;
  const tagName = payload.data.tag?.name;
  if (tagName && tagName !== refundTagName) {
    throw new Error(`Tag '${tagName}' does not match required tag '${refundTagName}'. Skipping ticket creation.`);
  }

  const conversationId = payload.data.item.id;
  const conversationUrl = buildConversationUrl(conversationId, payload.data.item.url, config.intercomAppId);

  // Prepare Zendesk ticket payload
  const zendeskPayload = {
    ticket: {
      subject: conversationUrl,
      comment: {
        body: `Intercom conversation ID: ${conversationId}`,
      },
    },
  };

  const zendeskUrl = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets.json`;
  const authHeader = `Bearer ${config.zendeskAccessToken}`;

  const response = await fetchImpl(zendeskUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: authHeader,
    },
    body: JSON.stringify(zendeskPayload),
  });

  if (!response.ok) {
    const errorText = await response.text().catch(() => '');
    throw new Error(`Zendesk API error: ${response.status} ${response.statusText} for POST ${zendeskUrl}. Response: ${errorText}`);
  }

  const result = (await response.json()) as { ticket: { id: number; subject: string; description: string } };

  return {
    ticketId: result.ticket.id,
    subject: result.ticket.subject,
    description: result.ticket.description,
  };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, IntercomWebhookPayload } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      zendeskSubdomain: 'testsubdomain',
      zendeskAccessToken: 'test-token',
      intercomAppId: 'test-app-id',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as IntercomWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.ticketId).toBe(123);
    expect(result.subject).toContain('intercom.com');
    expect(result.description).toContain('12345');
  });
});

describe('handle', () => {
  it('creates a Zendesk ticket with correct field mapping on happy path', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('zendesk.com/api/v2/tickets.json') && req.method === 'POST') {
        return jsonResponse({
          ticket: { id: 456, subject: 'https://app.intercom.com/conversation/12345', description: 'Intercom conversation ID: 12345', status: 'new' },
        }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation_part.tag.created',
      data: {
        item: { type: 'conversation', id: '12345', url: 'https://app.intercom.com/conversation/12345' },
        tag: { name: 'refund' },
      },
    };

    const config: ConnectorConfig = {
      zendeskSubdomain: 'mysub',
      zendeskAccessToken: 'secret-token',
      fetch,
    };

    const result = await handle(payload, config);

    expect(result.ticketId).toBe(456);
    expect(calls).toHaveLength(1);
    const call = calls[0];
    expect(call.method).toBe('POST');
    expect(call.url).toBe('https://mysub.zendesk.com/api/v2/tickets.json');
    expect(call.headers.get('authorization')).toBe('Bearer secret-token');
    expect(call.json).toEqual({
      ticket: {
        subject: 'https://app.intercom.com/conversation/12345',
        comment: { body: 'Intercom conversation ID: 12345' },
      },
    });
  });

  it('constructs conversation URL from intercomAppId when payload URL has placeholder', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('zendesk.com/api/v2/tickets.json') && req.method === 'POST') {
