          ticket: { id: 789, subject: 'https://app.intercom.com/a/apps/my-app-id/inbox/shared/all/conversation/999', description: 'Intercom conversation ID: 999', status: 'new' },
        }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation_part.tag.created',
      data: {
        item: { type: 'conversation', id: '999', url: 'https://app.intercom.com/a/apps/<app_id>/inbox/shared/all/conversation/999' },
        tag: { name: 'refund' },
      },
    };

    const config: ConnectorConfig = {
      zendeskSubdomain: 'mysub',
      zendeskAccessToken: 'secret-token',
      intercomAppId: 'my-app-id',
      fetch,
    };

    const result = await handle(payload, config);

    expect(result.ticketId).toBe(789);
    expect(calls[0].json).toEqual({
      ticket: {
        subject: 'https://app.intercom.com/a/apps/my-app-id/inbox/shared/all/conversation/999',
        comment: { body: 'Intercom conversation ID: 999' },
      },
    });
  });

