      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation_part.tag.created',
      data: { item: { type: 'conversation', id: '123' }, tag: { name: 'refund' } },
    };

    const config: ConnectorConfig = { zendeskSubdomain: 'sub', zendeskAccessToken: 'tok', fetch };

    await expect(handle(payload, config)).rejects.toThrow('Zendesk API error: 500 Internal Server Error for POST https://sub.zendesk.com/api/v2/tickets.json');
  });
